head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gRsnClssCdList = "";
scwin.pageSize = 50; // 페이지 size
scwin.totalCnt = 0; // 전체 row
scwin.pageNoCnt = 10; // page 번호 개수
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.gExcelTp = "1";
scwin.gDepCd;
scwin.gUpDepCd;
scwin.gEmpNo;
scwin.gLdMktTp = js_market;
scwin.gAcptNo;
scwin.gMainFormCd;
scwin.gFormVer;
scwin.gIsurCd;
scwin.gScnNm;
scwin.gKeyword;

// DisclosureSearchAppImpl.java 에서 사용중. vScrenID바꾸지 마세요 20170421

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function(e) {
    try {
        scwin.checkCond();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name cmb_PerPage_OnCloseUp
 * @description cmb Per Page On Close Up 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PerPage_OnCloseUp = function() {
    try {
        const vPerPage = cmb_PerPage.ValueOfIndex("VALUE", cmb_PerPage.Index);
        scwin.pageSize = vPerPage;
        // alert(pageSize);
        scwin.search();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.cmb_PerPage_OnCloseUp" });
    }
};

/**
 * @method
 * @name dts_scn_list_OnLoadError
 * @description dts_scn_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_scn_list_OnLoadError = function() {
    try {
        alert('dts_scn_list.OnLoadError() ' + dts_scn_list.errorMsg);
        CloseWin(0, mgrd_Grid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.dts_scn_list_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadError
 * @description dts_DsclList 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadError = function() {
    try {
        $c.win.alert + $c.data.getMessage("OnLoadError => " + dts_DsclList);
        CloseWin('', grd_Grid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.dts_DsclList_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclList_OnLoadCompleted
 * @description dts_DsclList 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DsclList_OnLoadCompleted = function(rowcount) {
    try {
        showload.style.display = "none";

        // 채권일경우 상장 제외 20170310
        if (getObjectValue(rdo_MKT_ID) === "4") {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: grd_Grid.ColumnProp("LIST_STAT_ID", 'Show') = false;*/
            X = false; /*ORG SRC: grd_Grid.ColumnProp("COM_ABBRV", 'color') = "Black";*/ X = "Black";
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            //
            // ********************************************************************

            /*ORG SRC: grd_Grid.ColumnProp("LIST_STAT_ID", 'Show') = true;*/
            X = true;
        }
        if (dts_DsclList.errorMsg) {
            alert("OnLoadCompleted => " + dts_DsclList.errorMsg);
        } else {
            /*
            //수정해야될 부분
            //데이터가 로드 되면 다음 내용을 처리 하도록 한다.
            //최초 조회인 경우 전체 row cnt를 구한다.
            if (vCurrPageNo == 0){
            	vCurrPageNo = 1;
            	totalCnt = dts_DsclList.NameString(0,"TOTALCNT");
            }
             */
            if (scwin.pageSize !== '0') {
                if (scwin.vCurrPageNo === 0) {
                    scwin.vCurrPageNo = 1;
                    scwin.totalCnt = dts_DsclList.NameString(0, "TOTALCNT");
                }
            } else {
                scwin.totalCnt = rowcount.getRowCount();
            }
            // alert(pageNoCnt +", "+pageSize+", "+totalCnt);
            // 페이지번호개수,pagesize, 데이터전체cnt,패널id(page번호 표시),패널 width
            FillGridHeader(scwin.pageNoCnt, scwin.pageSize, scwin.totalCnt, panel_page, 743);
        }

        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_Search.setDisabled(true);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
        CloseWin(scwin.totalCnt, grd_Grid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.dts_DsclList_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_scn_list_OnLoadCompleted
 * @description dts_scn_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_scn_list_OnLoadCompleted = function(rowcount) {
    try {
        let combo_text = "";
        for (let i = 0; i <= dts_scn_list.CountRow - 1; i++) {
            combo_text += cmb_scn_list.ValueOfIndex("TEXT", i) + ",";
        }
        panel_combo.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='16' width='100%'>" + "    <tr>" + "        <td align='left'  nowrap style='font-size__9pt; font-family:굴림;'>" + $c.str.replaceAll(combo_text.substring(0, combo_text.lastIndexOf(',')), " ", "") + "</td>";
        "    </tr>" + "</table>";

        // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        // btn_Search.disabled = false;
        // btn_Search.src = "../img/btn_select.gif";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.dts_scn_list_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_emp_OnLoadCompleted
 * @description dts_emp 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnLoadCompleted = function(rowcount) {
    // setObjectValue(cmb_EmpList, js_emp_no) ;

};

/**
 * @method
 * @name dts_emp_OnFilter
 * @description emp On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_emp_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "" || scwin.gDepCd === "UPTEAM") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            if (dts_emp.NameValue(row, "dep_cd") === scwin.gDepCd ||
                dts_emp.NameValue(row, "dep_cd") === "UPTEAM" ||
                dts_emp.NameValue(row, "dep_cd") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.dts_emp_OnFilter" });
    }
};

/**
 * @method
 * @name dts_dep_OnLoadCompleted
 * @description dts_dep 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    try {
        if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
            CopyDataSet(dts_dep, dts_dep1);
            scwin.addDsclTeamAll(rowcount);
            setObjectValue(cmb_TeamList, 'UPTEAM');
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.dts_dep_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_DsclList_excel_OnLoadError
 * @description dts_DsclList_excel 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.dts_DsclList_excel_OnLoadError = function() {
    try {
        $c.win.alert + $c.data.getMessage("엑셀저장에 실패하였습니다. : " + dts_DsclList_excel);
        showload.style.display = "none";
        btn_Excel.setDisabled(true);
        btn_Excel.setBackgroundImage("../img/btn_excelsave.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.dts_DsclList_excel_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_DsclList_excel_OnLoadCompleted
 * @description dts_DsclList_excel 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_DsclList_excel_OnLoadCompleted = function(rowcount) {
    try {
        showload.style.display = "none";
        if (scwin.gExcelTp === "1") {
            // 채권일경우 상장 제외 20170310
            if (getObjectValue(rdo_MKT_ID) === "4") {

                // ********************************************************************
                // [WebSquare 전환 추가] 원본 소스와 비교 필요
                //
                // ********************************************************************

                /*ORG SRC: grd_Grid_excel.ColumnProp("LIST_STAT_ID", 'Show') = false;*/
                X = false; /*ORG SRC: grd_Grid_excel.ColumnProp("COM_ABBRV", 'color') = "Black";*/ X = "Black";
            }
            grd_Grid_excel.GridToExcel("공시상세검색  목록", "", "8");
        } else {
            const responseCode = dts_DsclList_excel.NameString(1, "VALUE");
            const inside_email = dts_DsclList_excel.NameString(1, "TEXT");
            if (responseCode === "200") {
                alert("1만건 이상은 메일로 제공합니다.\n엑셀저장이 완료되면 등록된 이메일(" + inside_email + ")로 엑셀파일 링크가 전송됩니다.\n(5만건 기준 약 1분 소요).");
            } else {
                alert("엑셀저장에 실패하였습니다. [" + responseCode + "]");
            }
        }

        // 엑셀저장 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
        btn_Excel.setDisabled(true);
        btn_Excel.setBackgroundImage("../img/btn_excelsave.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.dts_DsclList_excel_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = function(row, colid) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "DOC_TITLE") {
            fn_OpenDisclViewer(scwin.gAcptNo, "R");
        } else if (colid === "ACPT_DDTM") {
            fn_OpenDisclAllList();
        } else if (colid === "COM_ABBRV") {
            fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name mgrd_Grid_OnLButtonDblClk
 * @description mgrd Grid On LButton Dbl Clk 처리
 * @param {*} type type
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @param {*} x x
 * @param {*} y y
 * @returns {void}
 * @hidden N
 */
scwin.mgrd_Grid_OnLButtonDblClk = function(type, row, colid, x, y) {
    try {
        // 클릭된 값 변수에 셋팅
        scwin.setContnId(row);
        if (colid === "DOC_TITLE") {
            fn_OpenDisclViewer(scwin.gAcptNo, "R");
        } else if (colid === "ACPT_DDTM") {
            fn_OpenDisclAllList();
        } else if (colid === "COM_ABBRV") {
            fn_PopupCorpInfo();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.mgrd_Grid_OnLButtonDblClk" });
    }
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function(e) {
    try {
        popUpCalendar2(edt_FromDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.img_FromCal_onclick" });
    }
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function(e) {
    try {
        popUpCalendar2(edt_ToDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.img_ToCal_onclick" });
    }
};

/**
 * @method
 * @name cmb_scn_list_OnSelChange2
 * @description cmb_scn_list 선택 변경 처리(2)(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cmb_scn_list_OnSelChange2 = async function() {
    try {
        scwin.gScnNm = cmb_scn_list.ValueOfIndex("VALUE", cmb_scn_list.Index);
        await scwin.ScnarioNmCall(scwin.gScnNm);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF_N003.cmb_scn_list_OnSelChange2" });
    }
};

/**
 * @method
 * @name cmb_TeamList_OnSelChange2
 * @description cmb_TeamList 선택 변경 처리(2)(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_TeamList_OnSelChange2 = function() {
    try {
        scwin.gDepCd = cmb_TeamList.ValueOfIndex("VALUE", cmb_TeamList.Index);
        if (scwin.gDepCd === '' || scwin.gDepCd === 'UPTEAM') {
            setObjectValue(cmb_EmpList, '');
        }
        dts_emp.UseFilter = true;
        dts_emp.Filter();
        dts_emp.SortExpr = "DEP_CD";
        dts_emp.Sort();
        if (scwin.gDepCd !== '' && scwin.gDepCd !== 'UPTEAM') {
            cmb_EmpList.ShowList();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.cmb_TeamList_OnSelChange2" });
    }
};

/**
 * @method
 * @name cmb_EmpList_OnCloseUp
 * @description cmb Emp List On Close Up 처리
 * @returns {void}
 * @hidden N
 */
scwin.cmb_EmpList_OnCloseUp = function() {
    try {
        const vDepCd = cmb_EmpList.ValueOfIndex("DEP_CD", cmb_EmpList.Index);
        if (vDepCd !== "") {
            setObjectValue(cmb_TeamList, vDepCd);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.cmb_EmpList_OnCloseUp" });
    }
};

/**
 * @method
 * @name cmb_IndTp_OnSelChange
 * @description cmb_IndTp 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_IndTp_OnSelChange = function() {
    try {
        let vValue = cmb_IndTp.ValueOfIndex("VALUE", cmb_IndTp.Index);
        if (vValue !== '') {
            // 전체일때 제외한 나머지경우
            scwin.checkComNmCond();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.cmb_IndTp_OnSelChange" });
    }
};

/**
 * @method
 * @name cmb_month_OnSelChange
 * @description cmb_month 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.cmb_month_OnSelChange = function() {
    try {
        let vValue = cmb_month.ValueOfIndex("VALUE", cmb_month.Index);
        if (vValue !== 'AA') {
            // 전체일때 제외한 나머지경우
            scwin.checkComNmCond();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.cmb_month_OnSelChange" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Excel_onclick = async function(e) {
    try {
        await scwin.excelDownload();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF_N003.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Cancel_onclick
 * @description 「취소」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_Cancel_onclick = function(e) {
    try {
        scwin.resetParam();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.btn_Cancel_onclick" });
    }
};

/**
 * @method
 * @name rdo_MKT_ID_OnSelChange
 * @description rdo_MKT_ID 선택 변경 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.rdo_MKT_ID_OnSelChange = function() {
    try {
        // fn_SetCtrlByMktId();
        // 채권일 경우 채권상장폐지여부 제외 항목으로 보이게끔 수정 20170310

        if (getObjectValue(rdo_MKT_ID) === '4') {
            showObj(label_3, false);
            showObj(label_24, true);
            scwin.setChkValue(chb_ListStatCd, "1");
        } else {
            showObj(label_3, true);
            showObj(label_24, false);
            scwin.setChkValue(chb_ListStatCd, false);
        }
        dts_Dscl_Cond.Reset();
        txb_rsn_cnt.setValue(dts_Dscl_Cond.CountRow);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF_N003.rdo_MKT_ID_OnSelChange" });
    }
};

/**
 * @method
 * @name img_FindForm_onclick
 * @description img_FindForm 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_FindForm_onclick = function(e) {
    try {
        // *** 셋팅할 필드명 정의를 아래처럼 해야함.
        // => 보고서명: txb_FormNm, 보고서코드 : txb_FormCd
