/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gUpDepCd = js_belngdepcd;
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2' || scwin.gLdMktTp === '4' || scwin.gLdMktTp === '6') {
        setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        showObj(panel_mkt, false);
    } else {
        setObjectValue(rdo_MKT_ID, '9');
    }

    // 채권일 경우 채권상장폐지여부 제외 항목으로 보이게끔 수정 20170310
    if (getObjectValue(rdo_MKT_ID) === '4') {
        showObj(label_3, false);
        showObj(label_24, true);
    } else {
        showObj(label_3, true);
        showObj(label_24, false);
    }

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.
    // 코넥스 추가
    if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34' || js_dep_cd.substring(0, 2) === '3B') {
        showObj(panel_dep_emp, true);
        scwin.gDepCd = "UPTEAM";
    } else {
        showObj(panel_dep_emp, false);
    }

    //  기간 from~ to  셋팅
    vCurDate = cGetToday("yyyymmdd");
    // edt_FromDate.text = cGetMinusDate2(vCurDate, 7);     // 일주일전 날짜
    edt_FromDate.setValue(vCurDate); // 현재날짜
    edt_ToDate.setValue(vCurDate); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    // dts_dep.DataID = "/CodeAction.do?method=listDepCdCode&For=R";
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 업종 셋팅
    const sbmOptions3 = {
        id : "sbm_dts_IndTp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_IndTp=body.content",
        isProcessMsg : false
    };

    const sbmRtn3 = await $c.sbm.executeDynamic(sbmOptions3);
    // TODO Stage2: sbmRtn3 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

