        url += "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT" + "&ISUR_CD=" + getObjectValue(txb_isur_cd) + "&FROM_DATE=" + getObjectValue(edt_FromDate) + "&TO_DATE=" + getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + scwin.gUpDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&BYPASS_YN=" + scwin.getChkValue(chb_ByPass) + "&FORM_CD=" + getObjectValue(txb_FormCd) + "&FORM_NM=" + getObjectValue(txb_FormNm) + "&KEYWORD=" + $c.str.replaceAll(getObjectValue(txb_keyword), "&", "＆") + "&FSS_UNQ_NO=" + getObjectValue(txb_FssUnqNo) + "&FSS_UNQ_NM=" + getObjectValue(txb_FssUnqNm) + "&ACNTCLS_MM=" + getObjectValue(cmb_month) + "&IND_TP=" + getObjectValue(cmb_IndTp) + "&KOR_YN=" + scwin.getChkValue(chb_kor_yn) + "&ENG_YN=" + scwin.getChkValue(chb_eng_yn) + "&LD_MKT_TP=" + getObjectValue(rdo_MKT_ID) + "&MAIN_YN=" + scwin.getChkValue(chb_main_yn) + "&ATCH_YN=" + scwin.getChkValue(chb_atch_yn) + "&DEP_TP=" + scwin.getChkValue(chb_dep_tp) + "&BASIS_TP=" + getObjectValue(cmb_Basis) + "&RSN_CLSS_CD_LIST=" + scwin.gRsnClssCdList + "&SCREN_ID=" + 'ULDSTF_N003.gfm' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_07;
        const sbmOptions = {
            id : "sbm_dts_DsclList_excel",
            action : "/DisclosureSearch.do",
            ref : "",
