/**
 * @method
 * @name checkComNmCond
 * @description 법인명이 있고 특정 다른 조건을 선택할때 메세지
 * @returns {void}
 * @hidden N
 */
scwin.checkComNmCond = function() {
    let vIsurCd = getObjectValue(txb_isur_cd);
    if (vIsurCd !== '') {
        alert("해당항목 선택시 법인코드(명)의 조건값이  초기화 됩니다.");
        setObjectValue(txb_isur_cd, '');
        setObjectValue(txb_com_abbrv, '');
        return;
    }
};

/**
 * @method
 * @name checkCond
 * @description 공시상세  목록검색 조건체크  : 사용자 클릭 -->
 * @returns {void}
 * @hidden N
 */
scwin.checkCond = function() {
    let vIsurCd = getObjectValue(txb_isur_cd);
    const vFssUnqNm = getObjectValue(txb_FssUnqNm);
    const vFormCd = getObjectValue(txb_FormCd);
    const vFormNm = getObjectValue(txb_FormNm);
    const vRsnclssCnt = getObjectValue(txb_rsn_cnt);
    let vKeyword = getObjectValue(txb_keyword);

    /*
    if (vKeyword == '' ) {
    	if (vIsurCd == '' &&  vFssUnqNm == '' && vFormNm == ''
    		&& (vRsnclssCnt =='' || vRsnclssCnt == '0') ) {
    		alert("법인코드(명), 제출의무자명, 공시제목, 사유분류 중 하나 이상을  입력하셔야 합니다." );
    		txb_isur_cd.focus();
    		return;
    	}
    }
     */

    // 일자 체크
    if (com.wconv.length(getObjectValue(edt_FromDate)) < 8) {
        alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (com.wconv.length(getObjectValue(edt_ToDate)) < 8) {
        alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.date.dateCompare(edt_FromDate, edt_ToDate) === false) {
        return;
    }

    // 4년 이상의 기간은 검색 할 수 없다
    /*
    var edt_FromDate_year = getObjectValue(edt_FromDate).substr(0,4);
    var edt_FromDate_month = getObjectValue(edt_FromDate).substr(4,2)-1;
    var edt_FromDate_day = getObjectValue(edt_FromDate).substr(6,2);
    var edt_FromDate_Date = new Date(edt_FromDate_year,edt_FromDate_month,edt_FromDate_day);

    var edt_ToDate_year = getObjectValue(edt_ToDate).substr(0,4);
    var edt_ToDate_month = getObjectValue(edt_ToDate).substr(4,2)-1;
    var edt_ToDate_day = getObjectValue(edt_ToDate).substr(6,2);
    var edt_ToDate_Date = new Date(edt_ToDate_year,edt_ToDate_month,edt_ToDate_day);
    var date_result = ( Date.parse(edt_ToDate_Date) - Date.parse(edt_FromDate_Date) ) / ( 1000*60*60*24 );

    if ( date_result > 1461) {
    	alert("검색기간은 4년 이상을 초과 할 수 없습니다." );
    	return;
    }
     */

    // 보고서코그 체크
    if (com.wconv.length(vFormCd) > 0 && com.wconv.length(vFormCd) !== 5) {
        alert("보고서코드 5자리를 입력하십시오.");
        txb_FormCd.focus();
        return;
    }
    // 언어구분 체크
    if (scwin.getChkValue(chb_kor_yn) === 0 && scwin.getChkValue(chb_eng_yn) === 0) {
        alert("언어구분은 한개이상 선택하십시오.");
        chb_kor_yn.focus();
        return;
    }

    // 제출유형 체크
    if (scwin.getChkValue(chb_main_yn) === 0 && scwin.getChkValue(chb_atch_yn) === 0) {
        alert("제출유형은 한개이상 선택하십시오.");
        chb_main_yn.focus();
        return;
    }
    if (scwin.chkAttchKeyword() === false) {
        return;
    }
    let sRsnClssCdList = "";
    let sFormUpclssCd;
    let sRsnClssCd;
    for (let i = 1; i <= dts_Dscl_Cond.CountRow; i++) {
        sFormUpclssCd = dts_Dscl_Cond.NameValue(i, "FORM_UPCLSS_CD");
        sRsnClssCd = dts_Dscl_Cond.NameValue(i, "RSN_CLSS_CD");
        if (sRsnClssCd !== "000") {
            sRsnClssCdList += (sFormUpclssCd + sRsnClssCd + ",");
        }
    }

    // 맨뒤에 ", " 제거 하기
    scwin.gRsnClssCdList = com.wconv.subStr(0, com.wconv.length(sRsnClssCdList) - 1);
    scwin.gDepCd = getObjectValue(cmb_TeamList);
    scwin.gEmpNo = getObjectValue(cmb_EmpList);
    if (scwin.gDepCd === "UPTEAM" && com.wconv.subStr(2, 4) === '00') {
        scwin.gUpDepCd = js_dep_cd;
    }
    if (js_dep_cd === '3410') {
        // 코 공시제도팀인 공시총괄팀으로 설정-- 2010.03.11
        scwin.gUpDepCd = '3400';
    }
    scwin.search();
};

/**
 * @method
 * @name search
 * @description 공시상세   목록검색 : 사용자 클릭 -->
 * @returns {void}
 * @hidden N
 */
scwin.search = function() {
    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
    btn_Search.setDisabled(false);
    btn_Search.setBackgroundImage("../img/btn_select_d.gif");
    scwin.vCurrPageNo = 0;
    dts_DsclList_excel.ClearAll();

    // 공시본문검색은 채권해제법인제외 조건을 선택하지 못하게 한다.
    // 검색엔진 테이블에 채권공시법인여부 칼럼이 없어서..
    if (txb_keyword.getValue() !== "") {
        if (getObjectValue(rdo_MKT_ID) === '4') {
            chb_ListStatCd.checked = false;
        }
    }
    let url = "";
    let url_cond = "&ISUR_CD=" + getObjectValue(txb_isur_cd) + "&FROM_DATE=" + getObjectValue(edt_FromDate) + "&TO_DATE=" + getObjectValue(edt_ToDate) + "&DEP_CD=" + scwin.gDepCd + "&UP_DEP_CD=" + scwin.gUpDepCd + "&EMP_NO=" + scwin.gEmpNo + "&LIST_STAT=" + scwin.getChkValue(chb_ListStatCd) + "&LAST_YN=" + scwin.getChkValue(chb_Last) + "&BYPASS_YN=" + scwin.getChkValue(chb_ByPass) + "&FORM_CD=" + getObjectValue(txb_FormCd) + "&FORM_NM=" + getObjectValue(txb_FormNm) + "&KEYWORD=" + $c.str.replaceAll(getObjectValue(txb_keyword), "&", "＆") + "&FSS_UNQ_NO=" + getObjectValue(txb_FssUnqNo) + "&FSS_UNQ_NM=" + getObjectValue(txb_FssUnqNm) + "&ACNTCLS_MM=" + getObjectValue(cmb_month) + "&IND_TP=" + getObjectValue(cmb_IndTp) + "&KOR_YN=" + scwin.getChkValue(chb_kor_yn) + "&ENG_YN=" + scwin.getChkValue(chb_eng_yn) + "&LD_MKT_TP=" + getObjectValue(rdo_MKT_ID) + "&RSN_CLSS_CD_LIST=" + scwin.gRsnClssCdList + "&MAIN_YN=" + scwin.getChkValue(chb_main_yn) + "&ATCH_YN=" + scwin.getChkValue(chb_atch_yn) + "&DEP_TP=" + scwin.getChkValue(chb_dep_tp) + "&BASIS_TP=" + getObjectValue(cmb_Basis) + "&PAGENO=" + scwin.vCurrPageNo + "&PAGESIZE=" + scwin.pageSize + "&SCREN_ID=" + 'ULDSTF_N003.gfm' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    // alert(url_cond);

    scwin.gKeyword = getObjectValue(txb_keyword);
    if (com.wconv.length(scwin.gKeyword) > 0) {
        // 본문검색 키워드가있을때 ...
        let iOpCnt = 0;
        if (scwin.gKeyword.indexOf("&") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("|") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (scwin.gKeyword.indexOf("!") > 0) {
            iOpCnt = iOpCnt + 1;
        }
        if (iOpCnt > 1) {
            alert("본문검색 키워드는 한 개만 사용할 수 있습니다.");
            txb_keyword.focus();
            return;
        }
        if (scwin.pageSize === 0) {
            alert("공시본문내용으로 검색할 경우에는 한페이지당 보여주는 갯수를 '전체'로 사용할 수 없습니다.");
            setObjectValue(cmb_PerPage, "50");
            cmb_PerPage.focus();
            return;
        }
        showObj(mgrd_Grid, true);
        showObj(grd_Grid, false);
        ShowWin(mgrd_Grid);

        // 1. 검색 건수부터 조회한다.
        url = "/DisclosureSearch.do?method=countDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=SCN_CNTSTAT_OUT";

        // alert("본문검색 카운트: "+url + url_cond);
        dts_scn_list.DataID = encodeURI(url + url_cond);
        dts_scn_list.reset();
        const vScnCur = dts_scn_list.NameString(dts_scn_list.CountRow, "SCN_CUR");
        // alert(dts_scn_list.CountRow +", "+vScnCur);

        if (dts_scn_list.CountRow > 0) {
            // 2.  Docruzer으로 검색
            url = "/DisclosureSearch.do?method=pagingDsclDetailSrchEngine" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
            url_cond += "&SCN_NM=" + vScnCur;
            // url_cond += "&SCN_NM=discls_internal";
            // alert("본문검색: "+url + url_cond);

            // alert("url-->"+url + url_cond);

            dts_DsclList.DataID = encodeURI(url + url_cond);
            dts_DsclList.reset();
            showObj(panel_scn, true);
            showObj(panel_combo, true);
            showObj(mgrd_Grid, true);
            showObj(grd_Grid, false);
            ShowWin(mgrd_Grid);
        } else {
            // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20150325
            btn_Search.setDisabled(true);
            btn_Search.setBackgroundImage("../img/btn_select.gif");
            scwin.vCurrPageNo = 0;
            dts_DsclList_excel.ClearData();
            dts_DsclList.ClearData();
            // showObj(mgrd_Grid, true);
            // showObj(grd_Grid, false);
            CloseWin(0, mgrd_Grid);
        }
    } else {
        // 본문검색 키워드가 없을때 ... 일반 DB검색
        url = "/DisclosureSearch.do?method=pagingDsclDetailSrch" + "&inputMessageId=DSCLDETAILCOND_IN" + "&outputMessageId=DSCLDETAILLIST_OUT";
        dts_DsclList.DataID = encodeURI(url + url_cond);
        dts_DsclList.reset();
        showObj(panel_scn, false);
        showObj(panel_combo, false);
        showObj(mgrd_Grid, false);
        showObj(grd_Grid, true);
        ShowWin(grd_Grid);
    }
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }
};

/**
 * @method
 * @name setChkValue
 * @description set Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @param {*} booleanVal booleanVal
 * @returns {void}
 * @hidden N
 */
scwin.setChkValue = function(obj, booleanVal) {
    // return (obj.checked) ? "Y" : "N";
    obj.checked = booleanVal;
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_DsclList.NameString(Number(obj), "ACPT_NO");
    scwin.gMainFormCd = dts_DsclList.NameString(Number(obj), "FORM_CD");
    scwin.gFormVer = dts_DsclList.NameString(Number(obj), "FORM_VER");
    scwin.gIsurCd = dts_DsclList.NameString(Number(obj), "ISUR_CD");

    // alert("부모창:"+gAcptNo+","+gMainFormCd+","+ gFormVer+","+ gIsurCd);
};

/**
 * @method
 * @name resetParam
 * @description reset Param 처리
 * @returns {void}
 * @hidden N
 */
scwin.resetParam = function() {
    vCurrDate = cGetToday("yyyymmdd"); // 현재날짜

    // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.
    if (js_dep_cd.substring(0, 2) === '26' || js_dep_cd.substring(0, 2) === '34') {
        scwin.gDepCd = "UPTEAM";
        setObjectValue(cmb_TeamList, scwin.gDepCd);
    }

    // 코넥스 추가를 추가 했었지만 2017.02.17 모든 시장을 보여달라고 해서 삭제함
    if (scwin.gLdMktTp === '1' || scwin.gLdMktTp === '2') {
        setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
    } else {
        // 코넥스는 유가, 코스닥도 볼 수 있음
        if (scwin.gLdMktTp === '6' || scwin.gLdMktTp === '4') {
            setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        } else {
            setObjectValue(rdo_MKT_ID, '9');
        }
    }

    // 채권일 경우 채권상장폐지여부 제외 항목으로 보이게끔 수정 20170310
    if (getObjectValue(rdo_MKT_ID) === '4') {
        showObj(label_3, false);
        showObj(label_24, true);
        scwin.setChkValue(chb_ListStatCd, "1");
    } else {
        showObj(label_3, true);
        showObj(label_24, false);
        scwin.setChkValue(chb_ListStatCd, false);
    }

    // setObjectValue(rdo_MKT_ID, js_market);

    setObjectValue(txb_isur_cd, "");
    setObjectValue(txb_com_abbrv, "");
    setObjectValue(edt_FromDate, vCurrDate);
    setObjectValue(edt_ToDate, vCurrDate);
    setObjectValue(cmb_EmpList, "");
    // setChkValue(chb_ListStatCd, false);
    scwin.setChkValue(chb_Last, false);
    scwin.setChkValue(chb_ByPass, false);
    setObjectValue(txb_FormCd, "");
    setObjectValue(txb_FormNm, "");
    setObjectValue(txb_keyword, "");
    setObjectValue(txb_FssUnqNo, "");
    setObjectValue(txb_FssUnqNm, "");
    setObjectValue(cmb_month, "");
    setObjectValue(cmb_IndTp, "");
    scwin.setChkValue(chb_kor_yn, true);
    scwin.setChkValue(chb_eng_yn, true);
    scwin.setChkValue(chb_main_yn, true);
    scwin.setChkValue(chb_atch_yn, true);
    scwin.setChkValue(chb_dep_tp, true);
    setObjectValue(cmb_Basis, "2");
    setObjectValue(cmb_PerPage, "50");
    setObjectValue(txb_rsn_cnt, "");
    dts_Dscl_Cond.ClearData();
    scwin.gRsnClssCdList = "";
};

