    /*ORG SRC: dts_dep.NameValue(rowcount + 1, "TEXT") = dts_dep1.NameValue(rowcount, "TEXT");*/
    X = dts_dep1.NameValue(rowcount, "TEXT"); /*ORG SRC: dts_dep.NameValue(rowcount + 1, "DEP_CD") = dts_dep1.NameValue(rowcount, "DEP_CD");*/ X = dts_dep1.NameValue(rowcount, "DEP_CD");
