/**
 * @method
 * @name chkAttchKeyword
 * @description 첨부서류만 선택하고 본문검색을 하고자할때 알림.
 * @returns {void}
 * @hidden N
 */
scwin.chkAttchKeyword = function() {
    let vKeyword = getObjectValue(txb_keyword);
    if (com.wconv.length(vKeyword) > 0) {
        if (scwin.getChkValue(chb_main_yn) === 0 &&
            scwin.getChkValue(chb_atch_yn) === 1) {
            alert('첨부서류만 선택한 후에는 공시본문내용 검색기능을 사용 할 수 없습니다.\n공시본문에서만 내용검색이 가능합니다.');
            txb_keyword.focus();
            return false;
        }
    }
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    showObj(grd_Grid_excel, false);
    showObj(mgrd_Grid_excel, false);
    showObj(panel_scn, false);
    showObj(panel_combo, false);
    showObj(mgrd_Grid, false);
    showObj(txb_FssUnqNo, false);

    // 패널라운드 처리
    PanelToGroupBox(panel_1);
    await scwin.setCode();
    Combo_CBDataSetLimit(cmb_PerPage);
    Combo_CBDataSetPeriod(cmb_PeriodTp);
    // 가우스헤더 셋팅
    const sbmOptions = {
        id : "sbm_dts_Dscl_Cond",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Dscl_Cond=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.checkCond();
    showload.style.display = "none";
};
